reordering_loss_delay_before:
pub(super) fn loss_delay(&self, ordinary: Duration, current_rtt: Duration) -> Duration {
    if self.observed_excess.is_zero() {
        ordinary
    } else {
        ordinary.max(current_rtt.saturating_add(self.observed_excess))
    }
}

reordering_loss_delay_instrumented:
pub(super) fn loss_delay(&self, ordinary: Duration, current_rtt: Duration) -> Duration {
    let selected = if self.observed_excess.is_zero() {
        ordinary
    } else {
        ordinary.max(current_rtt.saturating_add(self.observed_excess))
    };
    // Temporary native deadline observation; never changes loss authority.
    static TRACE: std::sync::OnceLock<Option<(Instant, std::sync::atomic::AtomicU64)>> =
        std::sync::OnceLock::new();
    if let Some((epoch, last)) = TRACE.get_or_init(|| {
        std::env::var_os("MPTUNNEL_NATIVE_MODEL_TRACE")
            .is_some_and(|value| value == "1")
            .then(|| (Instant::now(), std::sync::atomic::AtomicU64::new(u64::MAX)))
    }) {
        let second = Instant::now().saturating_duration_since(*epoch).as_secs();
        if last.swap(second, std::sync::atomic::Ordering::Relaxed) != second {
            let unix_ms = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis();
            eprintln!(
                "mptunnel_native_reordering ts_unix_ms={} ordinary_us={} current_rtt_us={} excess_us={} selected_us={} seen={} recoveries={}",
                unix_ms, ordinary.as_micros(), current_rtt.as_micros(),
                self.observed_excess.as_micros(), selected.as_micros(), self.seen,
                self.remaining_recoveries,
            );
        }
    }
    selected
}
